    const roomFor = (n = 1) => moveParticles.length + n < 1250;
    const DUST = ['#e8dcc0', '#d8c9a8', '#bfae8a', '#9c8c6c'];
    const ROCK = SIG_PALETTE.rock;

    // ── 그림 ──
