                    const x0 = dir > 0 ? Math.max(gm.mouth.x, me.x + 0.28 * me.w) : Math.min(gm.mouth.x, me.x - 0.28 * me.w);
                    // 겨누는 곳 — Y 자면 M (입보다 앞 8칸은 넘게), 아니면 상대 가슴
